import sys

def find_smallest_n(x):
    if x == 1:
        return 1
    n = 2
    while True:
        max_ones = 0
        if n % 2 == 0:
            max_ones = (n // 2) ** 2 * 2
        else:
            max_ones = (n // 2 + 1) * (n // 2) * 2 + (n // 2 + 1)
        if x <= max_ones:
            return n
        n += 1

x = int(sys.stdin.read().strip())
print(find_smallest_n(x))
